const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pendingOwners=new Set();
export function weightInsightMarkup(data){return data.cloud?'<section id="weight-insight" class="wi-panel" aria-label="Weight insight"><p role="status">Opening weight insights…</p></section>':'';}
export function mountWeightInsight({data,request}){
 const node=document.querySelector('#weight-insight');if(!node)return;
 const owner=data.viewer.id;
 let state,message='',working=false;
 const factText=(id,review)=>{const f=review.evidence.facts.find(f=>f.id===id);return f?new Intl.NumberFormat('en-AU',{maximumFractionDigits:2}).format(f.value)+' '+f.unit:'—';};
 const prose=(text,review)=>esc(text.replace(/\{([\w.]+)\}/g,(_,id)=>factText(id,review)).replace(/\b([\d,.]+) days? period\b/g,'$1-day period').replace(/\b([\d,.]+) days recorded days\b/g,'$1 recorded days'));
 function render(){
  if(!node.isConnected)return;const pending=pendingOwners.has(owner),consent=state?.consent?.enabled,review=state?.review;
  node.innerHTML=`<div class="wi-heading"><span class="wi-star" aria-hidden="true">✧</span><h2>What’s changing</h2><span>${data.dataset==='synthetic'?'Synthetic preview':'Gemini insight'}</span></div>${review?`<h3>${prose(review.report.headline,review)}</h3><p class="wi-explanation">${prose(review.report.explanation,review)}</p><p class="wi-next">${{'refresh-readings':'Next: record a fresh weigh-in to update the picture.','consistent-conditions':'Next: use similar weighing conditions for clearer comparisons.','keep-recording':'Next: keep logging so the trend has more observations.','inspect-readings':'Next: inspect the readings around the largest changes.'}[review.report.nextStep]}</p><div class="wi-evidence">${review.report.supportingFactIds.map(id=>{const f=review.evidence.facts.find(f=>f.id===id),labels={'history.days':'Recorded days','period.trendChange':'Trend change','recent.weeklyRate':'Recent weekly rate','recent.deviation':'Typical scale-to-trend gap','recent.range':'Scale range','latest.age':'Since last weigh-in','latest.trend':'Smoothed trend'};return `<div><strong>${esc(factText(id,review))}</strong><span>${esc(labels[id]||f.label)}</span></div>`;}).join('')}</div><p class="wi-meta">${review.stale?'Readings or timing changed. Update this insight.':'Based on your recorded weight history.'} Generated ${new Date(review.generatedAt).toLocaleDateString('en-AU')}.</p><details class="wi-method"><summary>Evidence and method</summary><p>The app calculates the trend, robust rate and recording coverage. Gemini interprets those facts; it does not generate the chart values.</p><ul>${review.report.factIds.map(id=>`<li>${esc(review.evidence.facts.find(f=>f.id===id).label)}: ${esc(factText(id,review))}</li>`).join('')}</ul><p>Model: ${esc(review.model)}. Weight alone cannot establish changes in fat or muscle.</p></details>`:`<h3>${consent===false?'Your chart works with AI off.':'The pattern behind the weigh-ins.'}</h3><p class="wi-explanation">${consent===true?'A concise reading of your trend, fluctuations and recent rate, grounded in your recorded numbers.':'Choose whether Gemini may analyse your weight values, relative timing and calculated trends. Notes, identity and locations stay out.'}</p>`}
  <div class="wi-actions">${consent===true?`<button type="button" id="generate-weight-insight" class="secondary-button" ${pending||working||!state.configured?'disabled':''}>${pending?'Analysing your weight history…':review?(review.stale?'Update insight':'Review current insight'):'Generate weight insight'}</button>`:consent!==false?`<button type="button" class="secondary-button" id="allow-weight-ai" ${working?'disabled':''}>Allow weight analysis</button><button type="button" class="text-button" id="decline-weight-ai" ${working?'disabled':''}>Keep AI off</button>`:''}</div>
  ${consent===true&&!state.configured?'<p class="wi-meta">Gemini is not configured for this environment. Your chart remains available.</p>':''}<p class="wi-status" role="status">${pending?'Analysing the recorded period. This may take a minute.':''}</p><p class="wi-error" role="alert">${esc(message)}</p>
  <details class="wi-sharing"><summary>Weight AI settings</summary><p>Separate from run analysis. Google’s free service may use inputs and outputs to improve products, including human review. Its terms say not to submit sensitive or personal information. <a href="https://ai.google.dev/gemini-api/terms" target="_blank" rel="noopener noreferrer">Read Google’s terms</a>.</p><p>Turning sharing off stops future calls and hides saved insights. It cannot recall data already sent. Enabling sharing alone makes no Gemini call.</p><button type="button" class="text-button" id="toggle-weight-ai" ${working?'disabled':''}>${consent===true?'Turn weight sharing off':'Allow weight analysis'}</button></details>`;
  node.querySelector('#generate-weight-insight')?.addEventListener('click',generate);
  node.querySelector('#allow-weight-ai')?.addEventListener('click',()=>preference(true));node.querySelector('#decline-weight-ai')?.addEventListener('click',()=>preference(false));node.querySelector('#toggle-weight-ai')?.addEventListener('click',()=>preference(consent!==true));
 }
 async function load(){try{state=await request('/api/private?route=weight-ai');render();}catch(e){if(node.isConnected)node.innerHTML=`<h2>Weight insight</h2><p role="alert">${esc(e.message)}</p><button type="button" id="retry-weight-ai" class="text-button">Retry</button>`;node.querySelector('#retry-weight-ai')?.addEventListener('click',load);}}
 async function preference(enabled){if(working)return;working=true;message='';render();try{await request('/api/private?route=weight-ai-consent',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled})});try{localStorage.setItem('mfa-weight-ai-changed',String(Date.now()));}catch{}await load();}catch(e){message=e.message;}finally{working=false;render();}}
 async function generate(){if(pendingOwners.has(owner))return;pendingOwners.add(owner);message='';render();try{await request('/api/private?route=weight-ai',{method:'POST'});await load();}catch(e){message=e.message;}finally{pendingOwners.delete(owner);render();dispatchEvent(new CustomEvent('mfa-weight-ai-settled',{detail:owner}));}}
 const refresh=e=>{if(e.key==='mfa-weight-ai-changed'){if(node.isConnected)void load();else removeEventListener('storage',refresh);}};addEventListener('storage',refresh);
 const settled=e=>{if(!node.isConnected){removeEventListener('mfa-weight-ai-settled',settled);return;}if(e.detail===owner)void load();};addEventListener('mfa-weight-ai-settled',settled);
 void load();
}
